// StudentSearch.jsx
import { useState } from "react";
import StudentLayout from "./StudentLayout";

const WILAYAS = ["All","Alger","Oran","Constantine","Annaba","Béjaïa","Tizi Ouzou","Blida","Sétif","Tlemcen","Batna"];
const TYPES   = ["All","On-site","Remote","Hybrid"];
const DOMAINS = ["All","Web Dev","Mobile","Data Science","DevOps","Cybersecurity","AI/ML","Embedded"];

const OFFERS = [
  { id:1,  title:"Full-Stack Web Developer",     company:"Sonatrach Digital",   logo:"🛢️",  wilaya:"Alger",    type:"On-site", domain:"Web Dev",      duration:"6 months", skills:["React","Node.js","PostgreSQL"], posted:"2 days ago",  applicants:14 },
  { id:2,  title:"Backend Engineer",             company:"Djezzy Tech",          logo:"📡",  wilaya:"Alger",    type:"Hybrid",  domain:"Web Dev",      duration:"4 months", skills:["Python","Django","Redis"],      posted:"3 days ago",  applicants:9  },
  { id:3,  title:"Flutter Mobile Developer",     company:"Cevital Digital",      logo:"🏭",  wilaya:"Béjaïa",   type:"Remote",  domain:"Mobile",       duration:"3 months", skills:["Flutter","Firebase","Dart"],    posted:"1 day ago",   applicants:6  },
  { id:4,  title:"Data Analyst Intern",          company:"BNA Digital",          logo:"🏦",  wilaya:"Alger",    type:"On-site", domain:"Data Science",  duration:"6 months", skills:["Python","SQL","Power BI"],      posted:"5 days ago",  applicants:21 },
  { id:5,  title:"DevOps / Cloud Intern",        company:"Ooredoo Labs",         logo:"🌐",  wilaya:"Alger",    type:"Hybrid",  domain:"DevOps",       duration:"4 months", skills:["Docker","Kubernetes","AWS"],    posted:"1 week ago",  applicants:7  },
  { id:6,  title:"AI/ML Research Intern",        company:"CERIST",               logo:"🔬",  wilaya:"Alger",    type:"On-site", domain:"AI/ML",        duration:"6 months", skills:["Python","TensorFlow","CV"],     posted:"4 days ago",  applicants:18 },
  { id:7,  title:"Cybersecurity Analyst",        company:"Algérie Télécom Labs", logo:"📞",  wilaya:"Alger",    type:"On-site", domain:"Cybersecurity", duration:"4 months", skills:["Linux","Wireshark","SIEM"],     posted:"3 days ago",  applicants:5  },
  { id:8,  title:"React Native Developer",       company:"Mobilis IT",           logo:"📱",  wilaya:"Oran",     type:"Remote",  domain:"Mobile",       duration:"3 months", skills:["React Native","TypeScript"],    posted:"6 days ago",  applicants:11 },
  { id:9,  title:"Embedded Systems Intern",      company:"Condor Electronics",   logo:"💻",  wilaya:"Blida",    type:"On-site", domain:"Embedded",     duration:"6 months", skills:["C","STM32","FreeRTOS"],         posted:"2 weeks ago", applicants:4  },
];

const typeColor = { "On-site":"badge-blue", "Remote":"badge-green", "Hybrid":"badge-orange" };

function OfferCard({ offer, onApply }) {
  const [saved, setSaved] = useState(false);
  return (
    <div className="card border border-slate-200 offer-card p-5">
      <div className="flex items-start justify-between gap-3 mb-3">
        <div className="flex items-start gap-3">
          <div className="w-11 h-11 rounded-xl bg-blue-50 border border-blue-100 flex items-center justify-center text-xl shrink-0">{offer.logo}</div>
          <div>
            <h3 className="font-syne font-bold text-slate-800 text-sm leading-snug">{offer.title}</h3>
            <p className="text-xs text-slate-400 mt-0.5">{offer.company} · {offer.wilaya}</p>
          </div>
        </div>
        <button
          onClick={() => setSaved(s => !s)}
          className={`shrink-0 text-lg transition-all hover:scale-110 ${saved ? "opacity-100" : "opacity-30 hover:opacity-70"}`}
          title={saved ? "Saved" : "Save offer"}
        >
          {saved ? "🔖" : "📑"}
        </button>
      </div>

      <div className="flex flex-wrap gap-1.5 mb-3">
        <span className={`badge ${typeColor[offer.type] || "badge-slate"}`}>{offer.type}</span>
        <span className="badge badge-slate">⏱ {offer.duration}</span>
        <span className="badge badge-slate">{offer.domain}</span>
      </div>
      <div className="flex flex-wrap gap-1.5 mb-4">
        {offer.skills.map(s => (
          <span key={s} className="skill-chip">{s}</span>
        ))}
      </div>

      <div className="flex items-center justify-between">
        <div className="text-xs text-slate-400">
          <span className="mr-2">🕐 {offer.posted}</span>
          <span>👥 {offer.applicants} applicants</span>
        </div>
        <button
          onClick={() => onApply(offer)}
          className="shimmer-btn text-white text-xs font-semibold px-4 py-2 rounded-lg"
        >
          Apply →
        </button>
      </div>
    </div>
  );
}

function ApplyModal({ offer, onClose }) {
  const [step, setStep] = useState(1);
  const [note, setNote] = useState("");

  if (!offer) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/50 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-md p-6 z-10">
        {step === 1 && (
          <>
            <div className="flex items-center gap-3 mb-5">
              <div className="w-12 h-12 rounded-xl bg-blue-50 border border-blue-100 flex items-center justify-center text-2xl">{offer.logo}</div>
              <div>
                <h3 className="font-syne font-bold text-slate-900 text-lg">{offer.title}</h3>
                <p className="text-sm text-slate-400">{offer.company}</p>
              </div>
            </div>
            <div className="bg-slate-50 rounded-xl p-4 mb-4 space-y-2">
              <div className="flex justify-between text-sm">
                <span className="text-slate-500">Location</span>
                <span className="font-medium text-slate-700">{offer.wilaya} · {offer.type}</span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-slate-500">Duration</span>
                <span className="font-medium text-slate-700">{offer.duration}</span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-slate-500">Domain</span>
                <span className="font-medium text-slate-700">{offer.domain}</span>
              </div>
            </div>
            <div className="mb-4">
              <label className="block text-sm font-semibold text-slate-700 mb-1.5">Cover note (optional)</label>
              <textarea
                rows={3}
                value={note}
                onChange={e => setNote(e.target.value)}
                placeholder="Why are you the right fit for this internship?"
                className="input-field resize-none"
                style={{minHeight:80}}
              />
            </div>
            <div className="text-xs text-slate-400 bg-blue-50 rounded-lg px-3 py-2 mb-5">
              📎 Your digital CV and skills profile will be sent automatically.
            </div>
            <div className="flex gap-3">
              <button onClick={onClose} className="flex-1 py-2.5 rounded-xl border border-slate-200 text-sm font-medium text-slate-600 hover:bg-slate-50 transition-colors">Cancel</button>
              <button onClick={() => setStep(2)} className="flex-1 shimmer-btn text-white text-sm font-semibold py-2.5 rounded-xl">Send application →</button>
            </div>
          </>
        )}
        {step === 2 && (
          <div className="text-center py-4">
            <div className="text-5xl mb-4">🎉</div>
            <h3 className="font-syne font-bold text-slate-900 text-xl mb-2">Application sent!</h3>
            <p className="text-sm text-slate-500 font-light mb-6">Your profile has been sent to <strong className="text-slate-700">{offer.company}</strong>. You'll be notified when they respond.</p>
            <button onClick={onClose} className="shimmer-btn text-white text-sm font-semibold px-8 py-2.5 rounded-xl">Done</button>
          </div>
        )}
      </div>
    </div>
  );
}export default function StudentSearch() {
  const [activePage]  = useState("search");
  const [search, setSearch] = useState("");
  const [wilaya, setWilaya] = useState("All");
  const [type,   setType]   = useState("All");
  const [domain, setDomain] = useState("All");
  const [applying, setApplying] = useState(null);

  const filtered = OFFERS.filter(o => {
    const q = search.toLowerCase();
    const matchQ = !q || o.company.toLowerCase().includes(q) || o.skills.some(s => s.toLowerCase().includes(q));
    const matchW = wilaya==="All" || o.wilaya===wilaya;
    const matchT = type==="All"   || o.type===type;
    const matchD = domain==="All" || o.domain===domain;
    return matchQ && matchW && matchT && matchD;
  });

  return (
    <StudentLayout active={activePage}>
      <div className="p-5 md:p-8">

        {/* Header */}
        <div className="anim-fade-up mb-6">
          <p className="text-xs font-semibold text-blue-500 uppercase tracking-widest mb-1">Offers</p>
          <h1 className="font-syne font-extrabold text-slate-900 text-2xl md:text-3xl tracking-tight">
            Find your internship
          </h1>
          <p className="text-slate-400 text-sm font-light mt-0.5">{filtered.length} offers matching your profile</p>
        </div>

        {/* Search + filters */}
        <div className="anim-fade-up anim-d1 card border border-slate-200 p-4 mb-6">
          <div className="flex flex-col md:flex-row gap-3">
            <div className="flex-1 relative">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm">🔍</span>
              <input
                type="text"
                placeholder="Search by title, company or skill..."
                value={search}
                onChange={e => setSearch(e.target.value)}
                className="input-field pl-9"
              />
            </div>
            <select value={wilaya} onChange={e=>setWilaya(e.target.value)} className="input-field md:w-36 select-field">
              {WILAYAS.map(w=><option key={w} value={w}>{w}</option>)}
            </select>
            <select value={type}   onChange={e=>setType(e.target.value)}   className="input-field md:w-32 select-field">
              {TYPES.map(t=><option key={t} value={t}>{t}</option>)}
            </select>
            <select value={domain} onChange={e=>setDomain(e.target.value)} className="input-field md:w-36 select-field">
              {DOMAINS.map(d=><option key={d} value={d}>{d}</option>)}
            </select>
            {(search !== ""|| type !== "All" || domain !== "All") && (
              <button
                onClick={()=>{setSearch("");setWilaya("All");setType("All");setDomain("All");}}
                className="text-xs font-medium text-slate-500 hover:text-red-500 border border-slate-200 px-3 py-2 rounded-xl transition-colors whitespace-nowrap"
              >
                Clear ✕
              </button>
            )}
          </div>
        </div>

        {/* Results grid */}
        {filtered.length > 0 ? (
          <div className="anim-fade-up anim-d2 grid md:grid-cols-2 xl:grid-cols-3 gap-4">
            {filtered.map(offer => (
              <OfferCard key={offer.id} offer={offer} onApply={setApplying} />
            ))}
          </div>
        ) : (
          <div className="anim-fade-up anim-d2 text-center py-20">
            <div className="text-5xl mb-3">🔍</div>
            <h3 className="font-syne font-bold text-slate-700 text-lg mb-1">No offers found</h3>
            <p className="text-sm text-slate-400">Try adjusting your filters or search terms.</p>
          </div>
        )}

      </div>

      {applying && <ApplyModal offer={applying} onClose={() => setApplying(null)} />}
    </StudentLayout>
  );
}
